# Now imagine you have 1000 not 30
# It would take just forever to compleate
# Now we will add cache to the code
def fibonacci(n ,cache={}):
   if n in cache:  
    return cache[n] # in this case your code automaticially saves a cache and speeds up your code
   if n <= 0:
       return 0
   elif n == 1:
       return 1
   else:
       return fibonacci(n-1) + fibonacci(n-2)
